  $$('[data-ts]', body).forEach(b => b.onclick = () => flTripSheet(sh(b.dataset.ts), again));
  $$('[data-pr]', body).forEach(b => b.onclick = () => flTripSheetPrint(sh(b.dataset.pr)));
  $$('[data-edit]', body).forEach(b => b.onclick = () => { const l = FL.find('duties', b.dataset.edit); flLegForm(sh(l.sheetId), l, again); });
  $$('[data-rm]', body).forEach(b => b.onclick = () => { const l = FL.find('duties', b.dataset.rm); confirmBox(`Remove the trip ${l.from} → ${l.to} from ${l.sheetId}? No pay is counted for it.`, () => { FL.upd('duties', l.id, { status: 'Cancelled' }); again(); }, 'Remove trip'); });
  $$('[data-cx]', body).forEach(b => b.onclick = () => { const s = sh(b.dataset.cx); confirmBox(`Cancel trip sheet ${s.id}? Its trips are cancelled and no pay is counted.`, () => { flLegs(s.id).forEach(l => FL.upd('duties', l.id, { status: 'Cancelled' })); FL.upd('sheets', s.id, { status: 'Cancelled' }); const v = FL.veh(s.vehicleId); if (v?.status === 'On Trip') Store.update('vehicles', v.id, { status: 'Available' }); toast(`${s.id} cancelled`); again(); }, 'Cancel trip sheet'); });
